from datetime import datetime, timedelta
from typing import Dict, List, Optional


class Appointment:
    def __init__(
        self,
        appointment_id: int,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
    ) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False


class BlockedSlot:
    def __init__(self, doctor: str, start: datetime, end: datetime) -> None:
        self.doctor = doctor
        self.start = start
        self.end = end


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}
        self._blocked_slots: List[BlockedSlot] = []

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        # Check if the patient already has an upcoming appointment (starts after `now`)
        for appt in self._appointments.values():
            if not appt.cancelled and appt.patient == patient and appt.start > now:
                raise ValueError("Patient already has an upcoming appointment.")

        # Check if the doctor is free in the requested time interval
        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available during the requested time slot.")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = Appointment(
            appt_id, patient, doctor, start, end
        )
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.cancelled:
            return

        appt.cancelled = True

        # If cancelled less than 24 hours before start, the slot remains blocked
        if (appt.start - now) < timedelta(hours=24):
            self._blocked_slots.append(
                BlockedSlot(appt.doctor, appt.start, appt.end)
            )

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            return False

        # Check against active appointments for the doctor
        for appt in self._appointments.values():
            if not appt.cancelled and appt.doctor == doctor:
                # Overlap check: start < other_end and end > other_start
                if start < appt.end and end > appt.start:
                    return False

        # Check against blocked slots for the doctor
        for slot in self._blocked_slots:
            if slot.doctor == doctor:
                if start < slot.end and end > slot.start:
                    return False

        return True
```

